window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-76213734b49291e7"]={"versions": [{"id": "FIG-76213734b49291e7", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-ECUC-Parametrisierungsdiagramm (UML-Klassendiagramm/Objektdiagramm) kombiniert mit einer tabellarischen Containerspezifikation für das Basissoftware-Modul Watchdog Manager (<code>WdgM</code>). Das Diagramm spezifiziert die Struktur des Konfigurationscontainers <code>WdgMActivation</code> innerhalb der AUTOSAR BSW-Konfiguration.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Spezifikation umfasst folgende Entitäten:</p>\n<ul class=\"fig-list\"><li><strong><code>WdgMActivation</code></strong>: Instanz bzw. Definition vom Typ <code>ChoiceContainerDef</code>. Dient als Auswahlcontainer zur Festlegung des Aktivierungsmechanismus des Watchdog Managers.\n</li><li><strong><code>WdgMActivationSchM</code></strong>: Untercontainer bzw. Parametercontainer-Definition vom Typ <code>ParamConfContainerDef</code>, angebunden über eine Komposition mit der Rollenbezeichnung <code>+choice</code>. Multiplizität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code> (<code>0..1</code>). Repräsentiert die Aktivierung über den Schedule Manager (Main Function activation).\n</li><li><strong><code>WdgMActivationGpt</code></strong>: Untercontainer bzw. Parametercontainer-Definition vom Typ <code>ParamConfContainerDef</code>, angebunden über eine Komposition mit der Rollenbezeichnung <code>+choice</code>. Multiplizität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code> (<code>0..1</code>). Repräsentiert die Aktivierung über den General Purpose Timer (GPT activation).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Laufzeitsequenz. Der Choice-Container erzwingt auf Konfigurationsebene eine exklusive oder optionale Auswahl zwischen zwei Aktivierungsarten: Entweder zyklische Ausführung über die Hauptfunktion des Schedule Managers (<code>WdgMActivationSchM</code>) oder zeitgesteuerte Auslösung über GPT-Timer-Callbacks (<code>WdgMActivationGpt</code>), jeweils mit einer Kardinalität von höchstens 1.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsvorgabe für die Parametrierung des WdgM-Moduls gemäß AUTOSAR-SWS. Konfigurationseditoren und Codegeneratoren müssen sicherstellen, dass innerhalb des Containers <code>WdgMActivation</code> genau eine der beiden Konfigurationsoptionen (<code>WdgMActivationSchM</code> oder <code>WdgMActivationGpt</code>) gewählt wird, um Konflikte bei der zyklischen Ansteuerung der Watchdog-Überwachungslogik zu vermeiden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-21b27a82fd4af2d5", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-ECUC-Parametrisierungsdiagramm (UML-Klassendiagramm/Objektdiagramm) kombiniert mit einer tabellarischen Containerspezifikation für das Basissoftware-Modul Watchdog Manager (<code>WdgM</code>). Das Diagramm spezifiziert die Struktur des Konfigurationscontainers <code>WdgMActivation</code> innerhalb der AUTOSAR BSW-Konfiguration.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Spezifikation umfasst folgende Entitäten:</p>\n<ul class=\"fig-list\"><li><strong><code>WdgMActivation</code></strong>: Instanz bzw. Definition vom Typ <code>ChoiceContainerDef</code>. Dient als Auswahlcontainer zur Festlegung des Aktivierungsmechanismus des Watchdog Managers.\n</li><li><strong><code>WdgMActivationSchM</code></strong>: Untercontainer bzw. Parametercontainer-Definition vom Typ <code>ParamConfContainerDef</code>, angebunden über eine Komposition mit der Rollenbezeichnung <code>+choice</code>. Multiplizität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code> (<code>0..1</code>). Repräsentiert die Aktivierung über den Schedule Manager (Main Function activation).\n</li><li><strong><code>WdgMActivationGpt</code></strong>: Untercontainer bzw. Parametercontainer-Definition vom Typ <code>ParamConfContainerDef</code>, angebunden über eine Komposition mit der Rollenbezeichnung <code>+choice</code>. Multiplizität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code> (<code>0..1</code>). Repräsentiert die Aktivierung über den General Purpose Timer (GPT activation).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Laufzeitsequenz. Der Choice-Container erzwingt auf Konfigurationsebene eine exklusive oder optionale Auswahl zwischen zwei Aktivierungsarten: Entweder zyklische Ausführung über die Hauptfunktion des Schedule Managers (<code>WdgMActivationSchM</code>) oder zeitgesteuerte Auslösung über GPT-Timer-Callbacks (<code>WdgMActivationGpt</code>), jeweils mit einer Kardinalität von höchstens 1.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsvorgabe für die Parametrierung des WdgM-Moduls gemäß AUTOSAR-SWS. Konfigurationseditoren und Codegeneratoren müssen sicherstellen, dass innerhalb des Containers <code>WdgMActivation</code> genau eine der beiden Konfigurationsoptionen (<code>WdgMActivationSchM</code> oder <code>WdgMActivationGpt</code>) gewählt wird, um Konflikte bei der zyklischen Ansteuerung der Watchdog-Überwachungslogik zu vermeiden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-76213734b49291e7", "to": "FIG-21b27a82fd4af2d5", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Tabellenkopf: Feld <code>SWS Item</code> von <code>--</code> auf <code>:</code> geändert; Feldbezeichnung <code>Choice Container Name</code> zu <code>Choice container Name</code> umformatiert.\n</li><li>UML-Diagrammrahmen: Der äußere Diagrammrahmen mit dem Kopf <code>object WdgMActivation</code> wurde entfernt.\n</li><li>Attribute-Anordnung: In den Kind-Containern wurden die Zeilen für Multiplizitäten getauscht (<code>WdgMActivationSchM</code> zeigt nun <code>lowerMultiplicity = 0</code> vor <code>upperMultiplicity = 1</code>, <code>WdgMActivationGpt</code> zeigt nun <code>upperMultiplicity = 1</code> vor <code>lowerMultiplicity = 0</code>).\n</li></ul>"}]};
